import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class MembershipMutationResult {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.Projects.Dtos.MembershipMutationResult",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @returns {boolean | Promise<boolean>}
   */
  get_succeeded() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Succeeded")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {boolean | Promise<boolean>}
   */
  get succeeded() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Succeeded")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_outcome() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Outcome")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get outcome() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Outcome")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {boolean | Promise<boolean>}
   */
  get_created() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Created")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {boolean | Promise<boolean>}
   */
  get created() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("Created")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {string[] | Promise<string[]>}
   */
  get_scopeIds() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ScopeIds")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => result.retrieveArray())
        : returnObjectIC.retrieveArray();
    }
  }
  /**
   * @returns {string[] | Promise<string[]>}
   */
  get scopeIds() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ScopeIds")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => result.retrieveArray())
        : returnObjectIC.retrieveArray();
    }
  }

  /**
   * @param {boolean} succeeded
   * @param {string} outcome
   * @param {boolean} created
   * @param {string[]} scopeIds
   */
  constructor(succeeded, outcome, created, scopeIds) {
    this.#args = [succeeded, outcome, created, scopeIds];
    if (this.#args?.length === 0) {
      this.#instance = MembershipMutationResult.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : MembershipMutationResult.type.createInstance(...this.#args);
    }
  }
}
