import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { MembershipMutationResult } from "./MembershipMutationResult.js";
import { Workspace } from "./Workspace.js";
import { WorkspaceMember } from "./WorkspaceMember.js";

export class WorkspaceService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.Workspaces.Facade.WorkspaceService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * Overload 1:
   * @param {string} token
   * @param {string} workspaceName
   * @returns {Promise<string>}
   * Overload 2:
   * @param {string} token
   * @param {string} workspaceName
   * @param {string} region
   * @param {number[]} logo
   * @returns {Promise<string>}
   */
  static async addWorkspace(...args) {
    try {
      const returnObjectIC = await (args !== undefined
        ? WorkspaceService.type
            .invokeStaticMethod(
              "AddWorkspace",
              ...GraftUtils.ArgsConverter(...args),
            )
            .execute()
        : WorkspaceService.type.invokeStaticMethod("AddWorkspace").execute());
      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @returns {Promise<Workspace[]>}
   */
  static async getWorkspacesByUserId(token) {
    try {
      const returnObjectIC = await WorkspaceService.type
        .invokeStaticMethod("GetWorkspacesByUserId", token)
        .execute();

      await GraftUtils.RegisterType(Workspace, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} workspaceId
   * @param {string} lastUsedProjectId
   * @returns {Promise<void>}
   */
  static async updateLastUsedProject(token, workspaceId, lastUsedProjectId) {
    try {
      WorkspaceService.type
        .invokeStaticMethod(
          "UpdateLastUsedProject",
          token,
          workspaceId,
          lastUsedProjectId,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} workspaceId
   * @returns {Promise<void>}
   */
  static async deleteWorkspace(token, workspaceId) {
    try {
      WorkspaceService.type
        .invokeStaticMethod("DeleteWorkspace", token, workspaceId)
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} userId
   * @param {string} workspaceId
   * @returns {Promise<string>}
   */
  static async getWorkspaceDetails(m2MToken, userId, workspaceId) {
    try {
      const returnObjectIC = await WorkspaceService.type
        .invokeStaticMethod(
          "GetWorkspaceDetails",
          m2MToken,
          userId,
          workspaceId,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} workspaceId
   * @param {string} authenticatedUserId
   * @param {string} level
   * @param {string} invitationId
   * @returns {Promise<MembershipMutationResult>}
   */
  static async applyInvitationMembership(
    m2MToken,
    workspaceId,
    authenticatedUserId,
    level,
    invitationId,
  ) {
    try {
      const returnObjectIC = await WorkspaceService.type
        .invokeStaticMethod(
          "ApplyInvitationMembership",
          m2MToken,
          workspaceId,
          authenticatedUserId,
          level,
          invitationId,
        )
        .execute();

      await GraftUtils.RegisterType(
        MembershipMutationResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} workspaceId
   * @param {string} authenticatedUserId
   * @param {string} invitationId
   * @returns {Promise<boolean>}
   */
  static async revertInvitationMembership(
    m2MToken,
    workspaceId,
    authenticatedUserId,
    invitationId,
  ) {
    try {
      const returnObjectIC = await WorkspaceService.type
        .invokeStaticMethod(
          "RevertInvitationMembership",
          m2MToken,
          workspaceId,
          authenticatedUserId,
          invitationId,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} workspaceId
   * @param {string} authenticatedUserId
   * @returns {Promise<boolean>}
   */
  static async hasWorkspaceMember(m2MToken, workspaceId, authenticatedUserId) {
    try {
      const returnObjectIC = await WorkspaceService.type
        .invokeStaticMethod(
          "HasWorkspaceMember",
          m2MToken,
          workspaceId,
          authenticatedUserId,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} workspaceId
   * @returns {Promise<WorkspaceMember[]>}
   */
  static async getWorkspaceMembers(token, workspaceId) {
    try {
      const returnObjectIC = await WorkspaceService.type
        .invokeStaticMethod("GetWorkspaceMembers", token, workspaceId)
        .execute();

      await GraftUtils.RegisterType(WorkspaceMember, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} workspaceId
   * @param {number[]} logo
   * @returns {Promise<void>}
   */
  static async updateWorkspaceLogo(token, workspaceId, logo) {
    try {
      WorkspaceService.type
        .invokeStaticMethod(
          "UpdateWorkspaceLogo",
          ...GraftUtils.ArgsConverter(token, workspaceId, logo),
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} workspaceId
   * @param {string} name
   * @returns {Promise<void>}
   */
  static async updateWorkspaceName(token, workspaceId, name) {
    try {
      WorkspaceService.type
        .invokeStaticMethod("UpdateWorkspaceName", token, workspaceId, name)
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} workspaceId
   * @param {string} otherUserId
   * @param {string} newLevel
   * @returns {Promise<void>}
   */
  static async updateWorkspaceMemberLevel(
    token,
    workspaceId,
    otherUserId,
    newLevel,
  ) {
    try {
      WorkspaceService.type
        .invokeStaticMethod(
          "UpdateWorkspaceMemberLevel",
          token,
          workspaceId,
          otherUserId,
          newLevel,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} userId
   * @param {string} workspaceId
   * @param {string} deletedUserId
   * @returns {Promise<void>}
   */
  static async deleteWorkspaceMember(
    m2MToken,
    userId,
    workspaceId,
    deletedUserId,
  ) {
    try {
      WorkspaceService.type
        .invokeStaticMethod(
          "DeleteWorkspaceMember",
          m2MToken,
          userId,
          workspaceId,
          deletedUserId,
        )
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<boolean>}
   */
  static async isHealthy() {
    try {
      const returnObjectIC = await WorkspaceService.type
        .invokeStaticMethod("IsHealthy")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
