import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";

export class InternalProjectCount {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.Projects.Dtos.InternalProjectCount",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @returns {string | Promise<string>}
   */
  get_userId() {
    {
      const returnObjectIC = this.instance.getInstanceField("UserId").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {string | Promise<string>}
   */
  get userId() {
    {
      const returnObjectIC = this.instance.getInstanceField("UserId").execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @param {string} value
   * @returns {string | Promise<string>}
   */
  set_userId(value) {
    {
      const returnObjectIC = this.instance
        .setInstanceField("UserId", value)
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  /**
   * @returns {number | Promise<number>}
   */
  get_projectCount() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ProjectCount")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @returns {number | Promise<number>}
   */
  get projectCount() {
    {
      const returnObjectIC = this.instance
        .getInstanceField("ProjectCount")
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }
  /**
   * @param {number} value
   * @returns {number | Promise<number>}
   */
  set_projectCount(value) {
    {
      const returnObjectIC = this.instance
        .setInstanceField("ProjectCount", value)
        .execute();

      return GraftUtils.isThenable(returnObjectIC)
        ? returnObjectIC.then((result) => GraftUtils.getValue(result))
        : GraftUtils.getValue(returnObjectIC);
    }
  }

  constructor(...args) {
    this.#args = args;
    if (this.#args?.length === 0) {
      this.#instance = InternalProjectCount.type.createInstance();
    } else {
      this.#instance = GraftUtils.isInvocationContext(this.#args[0])
        ? this.#args[0]
        : InternalProjectCount.type.createInstance(...this.#args);
    }
  }
}
