import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { ProjectCredentialAuthorizationResult } from "./ProjectCredentialAuthorizationResult.js";
import { ProjectKey } from "./ProjectKey.js";

export class ProjectKeyService {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "GC.Webportals.Projects.Facade.ProjectKeyService",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} name
   * @returns {Promise<void>}
   */
  static async deleteProjectKey(token, projectId, name) {
    try {
      ProjectKeyService.type
        .invokeStaticMethod("DeleteProjectKey", token, projectId, name)
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} projectKeyId
   * @returns {Promise<ProjectKey>}
   */
  static async getGatewayKey(token, projectId, projectKeyId) {
    try {
      const returnObjectIC = await ProjectKeyService.type
        .invokeStaticMethod("GetGatewayKey", token, projectId, projectKeyId)
        .execute();

      await GraftUtils.RegisterType(ProjectKey, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} username
   * @returns {Promise<ProjectKey>}
   */
  static async generatePersonalProjectKey(token, projectId, username) {
    try {
      const returnObjectIC = await ProjectKeyService.type
        .invokeStaticMethod(
          "GeneratePersonalProjectKey",
          token,
          projectId,
          username,
        )
        .execute();

      await GraftUtils.RegisterType(ProjectKey, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} name
   * @param {string} parentProjectKeyId
   * @returns {Promise<ProjectKey>}
   */
  static async generateGenericProjectKey(
    token,
    projectId,
    name,
    parentProjectKeyId,
  ) {
    try {
      const returnObjectIC = await ProjectKeyService.type
        .invokeStaticMethod(
          "GenerateGenericProjectKey",
          token,
          projectId,
          name,
          parentProjectKeyId,
        )
        .execute();

      await GraftUtils.RegisterType(ProjectKey, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @returns {Promise<ProjectKey[]>}
   */
  static async getGenericProjectKeys(token, projectId) {
    try {
      const returnObjectIC = await ProjectKeyService.type
        .invokeStaticMethod("GetGenericProjectKeys", token, projectId)
        .execute();

      await GraftUtils.RegisterType(ProjectKey, returnObjectIC, true);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} token
   * @param {string} projectId
   * @param {string} name
   * @returns {Promise<ProjectKey>}
   */
  static async regenerateProjectKey(token, projectId, name) {
    try {
      const returnObjectIC = await ProjectKeyService.type
        .invokeStaticMethod("RegenerateProjectKey", token, projectId, name)
        .execute();

      await GraftUtils.RegisterType(ProjectKey, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} username
   * @param {string} projectKey
   * @param {string} projectId
   * @returns {Promise<boolean>}
   */
  static async authorizeRegistryAccess(username, projectKey, projectId) {
    try {
      const returnObjectIC = await ProjectKeyService.type
        .invokeStaticMethod(
          "AuthorizeRegistryAccess",
          username,
          projectKey,
          projectId,
        )
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} projectKey
   * @param {string} username
   * @returns {Promise<void>}
   */
  static async verifyProjectKey(m2MToken, projectKey, username) {
    try {
      ProjectKeyService.type
        .invokeStaticMethod("VerifyProjectKey", m2MToken, projectKey, username)
        .execute();
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} credentials
   * @returns {Promise<ProjectCredentialAuthorizationResult>}
   */
  static async authorizeGpmgAccess(m2MToken, credentials) {
    try {
      const returnObjectIC = await ProjectKeyService.type
        .invokeStaticMethod("AuthorizeGpmgAccess", m2MToken, credentials)
        .execute();

      await GraftUtils.RegisterType(
        ProjectCredentialAuthorizationResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {string} m2MToken
   * @param {string} credentials
   * @returns {Promise<ProjectCredentialAuthorizationResult>}
   */
  static async authorizeArtifactFeedAccess(m2MToken, credentials) {
    try {
      const returnObjectIC = await ProjectKeyService.type
        .invokeStaticMethod(
          "AuthorizeArtifactFeedAccess",
          m2MToken,
          credentials,
        )
        .execute();

      await GraftUtils.RegisterType(
        ProjectCredentialAuthorizationResult,
        returnObjectIC,
        false,
      );
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @returns {Promise<boolean>}
   */
  static async isHealthy() {
    try {
      const returnObjectIC = await ProjectKeyService.type
        .invokeStaticMethod("IsHealthy")
        .execute();

      return GraftUtils.getValue(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
