/* eslint-disable no-console */
import { ConfigPriority, RuntimeBridge } from "hypertube-nodejs-sdk";

/* graft:esm-bootstrap-start */
if (typeof process !== "undefined" && process?.versions?.node != null) {
  const [{ createRequire }, { fileURLToPath }] = await Promise.all([
    import("node:module"),
    import("node:url"),
  ]);
  globalThis.__graftNodeRequire = createRequire(import.meta.url);
  const path = globalThis.__graftNodeRequire("path");
  globalThis.__graftPackageDir = path.dirname(fileURLToPath(import.meta.url));
}
/* graft:esm-bootstrap-end */

/**
 * Configuration class for Hypertube runtime initialization.
 * Handles loading configuration from environment variables, files, and default values.
 * Works in both Node.js and browser environments.
 */
export class GraftConfig {
  /** @type {string} */
  static graftName = "@graft/nuget-GC.Webportals.Projects";
  /** @type {string} */
  static graftConfigEnvVar = "GRAFTCODE_CONFIG_NUGET_GC_WEBPORTALS_PROJECTS";
  /** @type {string} */
  static runtimeName = "netcore";
  /** @type {string} */
  static module = "GC.Webportals.Projects";
  /** @type {string} */
  static host = "inmemory";
  /** @type {boolean} */
  static stateless = false;
  /** @type {RuntimeContext} */
  static rtmCtx = null;
  /** @type {Record<string, string | string[]>} */
  static headers = {};

  /**
   * Checks if the code is running in a Node.js environment.
   * @private
   * @returns {boolean} True if running in Node.js, false otherwise
   */
  static #isNodeEnvironment() {
    return typeof process !== "undefined" && process?.versions?.node != null;
  }

  /**
   * @private
   * @param {string} moduleId
   * @returns {any}
   */
  static #nodeRequire(moduleId) {
    return globalThis.__graftNodeRequire?.(moduleId);
  }

  /**
   * Lazily initializes Node.js require helper and package directory for hosted module resolution.
   * @private
   */
  static #ensureNodeBootstrap() {
    if (
      globalThis.__graftNodeRequire != null ||
      !GraftConfig.#isNodeEnvironment()
    ) {
      return;
    }

    if (typeof __dirname !== "undefined" && typeof require !== "undefined") {
      globalThis.__graftPackageDir = __dirname;
      globalThis.__graftNodeRequire = require;
    }
  }

  /**
   * @private
   * @param {string} candidate
   * @returns {boolean}
   */
  static #pathExists(candidate) {
    const fs = GraftConfig.#nodeRequire("fs");
    return Boolean(fs?.existsSync?.(candidate));
  }

  /**
   * @private
   * @param {string} packageDir
   * @param {string} moduleRoot
   */
  static #copyResourcesToModuleRoot(packageDir, moduleRoot) {
    const fs = GraftConfig.#nodeRequire("fs");
    const path = GraftConfig.#nodeRequire("path");
    if (!fs?.existsSync || !path) {
      return;
    }

    const resourcesDir = path.join(packageDir, "resources");
    if (!fs.existsSync(resourcesDir)) {
      return;
    }

    try {
      if (typeof fs.cpSync === "function") {
        fs.cpSync(resourcesDir, moduleRoot, { recursive: true, force: true });
        return;
      }
      if (typeof fs.mkdirSync === "function") {
        fs.mkdirSync(moduleRoot, { recursive: true });
      }
    } catch {
      return;
    }
  }

  /**
   * @private
   * @param {string} packageDir
   * @param {string} moduleToken
   * @returns {string}
   */
  static #joinPackageModulePath(packageDir, moduleToken) {
    const path = GraftConfig.#nodeRequire("path");
    if (!path) {
      return moduleToken;
    }

    const segments = String(moduleToken).split(/[/\\]/).filter(Boolean);
    return path.join(packageDir, ...segments);
  }

  /**
   * Resolves the hosted module folder inside the installed @graft package.
   * @private
   * @param {string} packageDir
   * @param {string} moduleToken
   * @returns {string}
   */
  static #resolveHostedModulePath(packageDir, moduleToken) {
    const path = GraftConfig.#nodeRequire("path");
    if (!path) {
      return moduleToken;
    }

    const segments = String(moduleToken).split(/[/\\]/).filter(Boolean);
    const moduleRoot = GraftConfig.#joinPackageModulePath(
      packageDir,
      moduleToken,
    );
    GraftConfig.#copyResourcesToModuleRoot(packageDir, moduleRoot);

    const candidates = [
      moduleRoot,
      path.join(packageDir, "resources", ...segments),
    ];

    if (segments.length > 0) {
      const firstSegment = segments[0];
      const rest = segments.slice(1);
      for (const variant of new Set([
        firstSegment.replace(/_/g, "-"),
        firstSegment.replace(/-/g, "_"),
      ])) {
        if (variant !== firstSegment) {
          candidates.push(path.join(packageDir, variant, ...rest));
          candidates.push(path.join(packageDir, "resources", variant, ...rest));
        }
      }
    }

    for (const candidate of candidates) {
      if (GraftConfig.#pathExists(candidate)) {
        return candidate;
      }
    }

    return moduleRoot;
  }

  /**
   * @private
   * @returns {string}
   */
  static #resolvePackageModulePath() {
    if (!GraftConfig.#isNodeEnvironment()) {
      return GraftConfig.module;
    }

    const path = GraftConfig.#nodeRequire("path");
    if (!path) {
      return GraftConfig.module;
    }

    const moduleToken = GraftConfig.module;
    let packageDir = globalThis.__graftPackageDir;

    if (!packageDir) {
      const graftPackage = GraftConfig.graftName.startsWith("@graft/")
        ? path.join(
            "node_modules",
            "@graft",
            GraftConfig.graftName.substring("@graft/".length),
          )
        : GraftConfig.graftName;
      packageDir = path.join(process.cwd(), graftPackage);
    }

    return GraftConfig.#resolveHostedModulePath(packageDir, moduleToken);
  }

  /**
   * Adds configuration to Hypertube with the specified priority.
   * @private
   * @param {ConfigPriority} priority - The priority level for the configuration
   * @param {string} config - The configuration string to add
   */
  static #addConfigToHypertube(priority, config) {
    RuntimeBridge.addConfig(priority, config);
  }

  /**
   * @private
   * @param {string} p
   * @returns {string}
   */
  static #resolveConfigPath(p) {
    if (!GraftConfig.#isNodeEnvironment()) {
      return p || "";
    }

    const path = GraftConfig.#nodeRequire("path");
    if (!path) {
      return p || "";
    }

    try {
      if (!p || !String(p).trim()) {
        return p || "";
      }
      if (path.isAbsolute(p)) {
        return path.normalize(p);
      }
      return path.resolve(process.cwd(), p);
    } catch {
      return p || "";
    }
  }

  /**
   * @private
   * @param {ConfigPriority} priority
   * @param {string} priorityName
   * @param {string} varName
   */
  static #tryAddFromEnv(priority, priorityName, varName) {
    if (!GraftConfig.#isNodeEnvironment() || !process?.env) {
      console.log(
        "[GraftConfig] Configuration priority=" +
          priorityName +
          " source=environment variable=" +
          varName +
          " - cannot be found",
      );
      return;
    }
    const v = process.env[varName];
    if (v != null && String(v).trim() !== "") {
      GraftConfig.#addConfigToHypertube(priority, varName);
    } else {
      console.log(
        "[GraftConfig] Configuration priority=" +
          priorityName +
          " source=environment variable=" +
          varName +
          " - cannot be found",
      );
    }
  }

  /**
   * @private
   * @param {ConfigPriority} priority
   * @param {string} priorityName
   * @param {string} fileNameOrPath
   */
  static #tryAddFromFile(priority, priorityName, fileNameOrPath) {
    const resolved = GraftConfig.#resolveConfigPath(fileNameOrPath);
    if (!GraftConfig.#isNodeEnvironment()) {
      console.log(
        "[GraftConfig] Configuration priority=" +
          priorityName +
          " source=file path=" +
          resolved +
          " - cannot be found",
      );
      return;
    }

    const fs = GraftConfig.#nodeRequire("fs");
    if (!fs) {
      console.log(
        "[GraftConfig] Configuration priority=" +
          priorityName +
          " source=file path=" +
          resolved +
          " - cannot be found",
      );
      return;
    }

    try {
      if (fs.existsSync(resolved)) {
        GraftConfig.#addConfigToHypertube(priority, resolved);
      } else {
        console.log(
          "[GraftConfig] Configuration priority=" +
            priorityName +
            " source=file path=" +
            resolved +
            " - cannot be found",
        );
      }
    } catch {
      console.log(
        "[GraftConfig] Configuration priority=" +
          priorityName +
          " source=file path=" +
          resolved +
          " - cannot be found",
      );
    }
  }

  /**
   * @private
   * @param {string} connectionString
   */
  static #registerDefaultLibrary(connectionString) {
    GraftConfig.#addConfigToHypertube(
      ConfigPriority.DefaultLibrary,
      connectionString,
    );
  }

  /**
   * Sets user configuration with User priority.
   * @param {string} config - The configuration string to set
   */
  static setConfig(config) {
    GraftConfig.#addConfigToHypertube(ConfigPriority.User, config);
  }

  /**
   * Sets default headers for the current runtime connection.
   * @param {Record<string, string | string[]>} headers
   */
  static setHeaders(headers) {
    if (GraftConfig.rtmCtx == null) {
      this.headers = headers;
    } else {
      GraftConfig.rtmCtx.connectionData.setHeaders(headers);
    }
  }

  /**
   * Invokes an async function with temporary thread-local headers.
   * @param {() => Promise<any>} func
   * @param {Record<string, string | string []>} headers
   * @returns {Promise<any>}
   */
  static async invokeWithHeaders(func, headers) {
    GraftConfig.init();
    const previous = this.rtmCtx.connectionData.getThreadLocalHeaders();
    this.rtmCtx.connectionData.setThreadLocalHeaders(headers);
    try {
      return await func();
    } finally {
      this.rtmCtx.connectionData.setThreadLocalHeaders(previous);
    }
  }

  /** @type {string|null} */
  static #runtimeConfigEnvVarOverride = null;

  /**
   * Overrides the runtime-specific configuration environment variable name.
   * Must be called before the first {@link GraftConfig.init}.
   * @param {string} envVarName
   */
  static setRuntimeConfigEnvVar(envVarName) {
    if (!envVarName?.trim()) {
      throw new Error("Environment variable name cannot be null or empty.");
    }
    if (GraftConfig.rtmCtx != null) {
      throw new Error(
        "Cannot set runtime config environment variable after initialization.",
      );
    }
    GraftConfig.#runtimeConfigEnvVarOverride = envVarName;
  }

  static #resolveRuntimeConfigEnvVar() {
    return (
      GraftConfig.#runtimeConfigEnvVarOverride ?? GraftConfig.graftConfigEnvVar
    );
  }

  /**
   * Initializes the runtime context and loads configurations in priority order.
   */
  static init() {
    if (GraftConfig.rtmCtx != null) {
      return;
    }

    if (GraftConfig.#isNodeEnvironment()) {
      GraftConfig.#ensureNodeBootstrap();
      GraftConfig.module = GraftConfig.#resolvePackageModulePath();
    }

    GraftConfig.#tryAddFromEnv(
      ConfigPriority.RuntimeSpecificEnv,
      "RuntimeSpecificEnv",
      GraftConfig.#resolveRuntimeConfigEnvVar(),
    );
    GraftConfig.#tryAddFromEnv(
      ConfigPriority.GlobalEnv,
      "GlobalEnv",
      "GRAFTCODE_CONFIG",
    );
    GraftConfig.#tryAddFromFile(
      ConfigPriority.RuntimeSpecificFile,
      "RuntimeSpecificFile",
      `${GraftConfig.graftName}-config.json`,
    );
    GraftConfig.#tryAddFromFile(
      ConfigPriority.RuntimeSpecificFile,
      "RuntimeSpecificFile",
      `${GraftConfig.graftName}-config.yaml`,
    );
    GraftConfig.#tryAddFromFile(
      ConfigPriority.RuntimeSpecificFile,
      "RuntimeSpecificFile",
      `${GraftConfig.graftName}-config.txt`,
    );
    GraftConfig.#tryAddFromFile(
      ConfigPriority.GlobalFile,
      "GlobalFile",
      "graftcode-config.json",
    );
    GraftConfig.#tryAddFromFile(
      ConfigPriority.GlobalFile,
      "GlobalFile",
      "graftcode-config.yaml",
    );
    GraftConfig.#tryAddFromFile(
      ConfigPriority.GlobalFile,
      "GlobalFile",
      "graftcode-config.txt",
    );

    const defaultConfig = `name=${GraftConfig.graftName}; runtime=${GraftConfig.runtimeName}; modules=${GraftConfig.module}; host=${GraftConfig.host}; stateless=${GraftConfig.stateless}`;
    GraftConfig.#registerDefaultLibrary(defaultConfig);
    GraftConfig.rtmCtx = RuntimeBridge.initializeRc(GraftConfig.graftName);
    GraftConfig.rtmCtx.connectionData.setHeaders(GraftConfig.headers);
  }
}
